(function(){
  'use strict';
  const core=GpaCore,$=id=>document.getElementById(id),defaults=core.example();
  let courses=[],rule=structuredClone(defaults.rule),preview=[],hasCalculated=false,lastResult=null,toastTimer;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const f=x=>Number.isFinite(x)?x.toFixed(4):'—',short=x=>Number.isFinite(x)?String(Number(x.toFixed(6))):'—';
  const uid=()=>crypto.randomUUID?crypto.randomUUID():'course-'+Date.now()+'-'+Math.random().toString(36).slice(2);
  function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
  function getInput(){return {currentGpa:$('current-gpa').value,historyCredits:$('history-credits').value,historyPoints:$('history-points').value,target:$('target-gpa').value,rule:structuredClone(rule),courses:structuredClone(courses)};}
  function ratingOptions(value){let html='<option value="">留空，自动分配等级</option>';for(const r of rule.ratings)html+='<option value="'+esc(r.name)+'" '+(value===r.name?'selected':'')+'>'+esc(r.name)+'（'+esc(r.gpa)+'）</option>';if(value&&!rule.ratings.some(r=>r.name===value))html+='<option selected value="'+esc(value)+'">'+esc(value)+'（未配置）</option>';return html;}
  function typeOptions(type,includeBlank=false){return (includeBlank?'<option value="">请补选</option>':'')+'<option value="numeric" '+(type==='numeric'?'selected':'')+'>百分制</option><option value="rating" '+(type==='rating'?'selected':'')+'>等级评价</option>';}
  function renderCourses(){
    $('course-body').innerHTML=courses.map((c,i)=>'<tr data-index="'+i+'"><td><input data-field="name" aria-label="第 '+(i+1)+' 门课程名称" value="'+esc(c.name)+'" placeholder="课程名称"></td><td><input data-field="credits" aria-label="'+esc(c.name||'课程')+'学分" type="number" min="0" step="any" value="'+esc(c.credits)+'"></td><td><select data-field="type" aria-label="'+esc(c.name||'课程')+'评分方式">'+typeOptions(c.type)+'</select></td><td>'+(c.type==='rating'?'<select data-field="fixed" aria-label="'+esc(c.name||'课程')+'预计等级">'+ratingOptions(c.fixed)+'</select>':'<input data-field="fixed" aria-label="'+esc(c.name||'课程')+'固定成绩" type="number" min="0" max="100" step="any" placeholder="留空，自动分配" value="'+esc(c.fixed)+'">')+'</td><td><button class="icon-button" data-remove="'+i+'" aria-label="删除'+esc(c.name||'课程')+'">×</button></td></tr>').join('');
    $('course-empty').hidden=!!courses.length;updateCount();showCourseResults();
  }
  function updateCount(){const total=courses.reduce((a,c)=>a+(Number(c.credits)||0),0);$('course-count').textContent=courses.length+' 门 · '+short(total)+' 学分';}
  function showCourseResults(){
    $('course-results').hidden=!lastResult;
    $('result-course-body').innerHTML=(lastResult?.rows||[]).map((row,i)=>'<tr><td>'+esc(row.name)+'</td><td>'+esc(short(row.credits))+'</td><td class="suggestion'+(row.fixed?' fixed':'')+'" data-suggestion="'+i+'">'+(row.score===null?'—':esc(row.score)+(row.type==='numeric'?' 分':'')+(row.fixed?' · 已固定':''))+'</td><td class="result-gpa" data-gpa="'+i+'">'+(row.score===null?'—':f(row.gp))+'</td></tr>').join('');
  }
  function clearResults(message){lastResult=null;showCourseResults();$('status-badge').textContent='检查输入';$('status-badge').className='badge error';$('result-title').textContent='还需要核对一些信息';$('result-description').textContent=message;for(const id of ['metric-forecast','metric-max','metric-required'])$(id).textContent='—';$('result-notes').replaceChildren();$('result-summary').textContent='补全或修正输入后会自动重新计算。';$('progress-fill').style.width='0';$('progress-marker').style.left='0';$('progress-start').textContent='当前 —';$('progress-target').textContent='目标 —';$('progress-caption').textContent='成绩与换算规则须使用相同的绩点制度。';}
  function calculate(){
    hasCalculated=true;let result;try{result=core.solve(getInput());}catch(e){clearResults(e.message);return null;}lastResult=result;showCourseResults();
    const ok=result.feasible;$('status-badge').textContent=ok?'目标可达':'当前条件不可达';$('status-badge').className='badge'+(ok?'':' error');
    $('result-title').textContent=ok?'这是一套可以达标的成绩组合':'最高成绩也暂时达不到目标';
    $('result-description').textContent=ok?(result.allFixed?'全部课程已有固定成绩，下面是按这些成绩计算的结果。':'按下方建议取得最终总评分数和等级，累计绩点将达到 '+f(result.forecast)+'。留空课程的成绩是待达到的目标；可固定某一科，再重新分配其余课程。'):'在当前学校规则和固定成绩下，最高可达 '+f(result.max)+'，距目标还差 '+f(result.gap)+'。可以检查课程、调整固定成绩或降低目标。';
    $('metric-forecast').textContent=ok?f(result.forecast):'—';$('metric-max').textContent=f(result.max);$('metric-required').textContent=f(Math.max(0,result.requiredSemesterGpa));
    const scale=Number(rule.scale);$('progress-fill').style.width=Math.min(100,100*(ok?result.forecast:result.max)/scale)+'%';$('progress-marker').style.left=Math.min(100,100*result.target/scale)+'%';$('progress-start').textContent='当前 '+f(result.current);$('progress-target').textContent='目标 '+f(result.target);$('progress-caption').textContent='学期结束累计 '+short(result.totalCredits)+' 学分 · 本学期 '+short(result.newCredits)+' 学分';
    const notes=[];if(!result.exactHistory)notes.push('<p class="warning">当前绩点可能经过舍入，结果为估算。填写精确历史学分绩点合计可减少误差。</p>');
    const grades=result.rows.filter(x=>x.type==='rating'&&x.score!==null);if(grades.length)notes.push('<p>等级'+(ok?'方案':'固定成绩')+'：'+grades.map(x=>esc(x.name)+' '+esc(x.score)+(x.fixed?'（固定）':'（建议）')).join('；')+'。</p>');
    if(result.freeCount&&ok)notes.push('<p>按本方案的等级成绩，未固定百分制课程 '+result.freeCount+' 门，共 '+short(result.freeCredits)+' 学分，还需贡献至少 '+short(Math.max(0,result.remainingPoints))+' 学分绩点。</p>');
    if(result.minimumSuffices&&ok)notes.push('<p>未固定课程按已配置的最低及格成绩即可达标。</p>');
    notes.push('<p>按未舍入数值判断是否达标；成绩方案可互相补偿。</p>');$('result-notes').innerHTML=notes.join('');
    const free=result.rows.filter(x=>x.type==='numeric'&&!x.fixed);
    $('result-summary').textContent=!ok?'表中保留固定成绩；未固定课程不分配无法达标的成绩。':free.length?'本方案未固定考试课合计 '+short(free.reduce((a,x)=>a+x.score,0))+' 分，平均 '+short(free.reduce((a,x)=>a+x.score,0)/free.length)+' 分。'+(new Set(free.map(x=>x.credits)).size>1?'各科学分不同，以加权绩点为准。':''):result.freeRatingCount?'未填写预计成绩的等级课程已分配建议等级，取得这些等级即可达标。':'所有课程均按下方固定成绩计算。';
    return result;
  }
  function refresh(){if(hasCalculated)calculate();}
  function refreshRatingOptions(){for(const row of $('course-body').querySelectorAll('tr')){const c=courses[Number(row.dataset.index)];if(c.type==='rating')row.querySelector('[data-field="fixed"]').innerHTML=ratingOptions(c.fixed);}}
  function updateFormula(){const band=rule.mode==='bands';$('linear-editor').hidden=band;$('bands-editor').hidden=!band;$('scale-label').textContent='/ '+short(Number(rule.scale));$('formula-preview').textContent='及格：绩点 = '+rule.base+' +（成绩 − '+rule.passScore+'）× '+rule.step+'；不及格：0';}
  function renderRule(){$('gpa-scale').value=rule.scale;$('rule-mode').value=rule.mode;$('pass-score').value=rule.passScore;$('band-pass-score').value=rule.passScore;$('base-gpa').value=rule.base;$('gpa-step').value=rule.step;renderBands();renderRatings();updateFormula();}
  function renderBands(){$('band-rows').innerHTML='<div class="band-labels"><span>下限（含）</span><span>上限</span><span>绩点</span></div>'+rule.bands.map((b,i)=>'<div class="band-row" data-band="'+i+'">'+['min','max','gpa'].map(k=>'<input data-key="'+k+'" type="number" min="0" step="any" value="'+esc(b[k])+'" aria-label="第 '+(i+1)+' 段'+({min:'下限',max:'上限',gpa:'绩点'}[k])+'">').join('')+'<button class="icon-button" data-remove-band="'+i+'" aria-label="删除第 '+(i+1)+' 段">×</button></div>').join('');}
  function renderRatings(){$('rating-rows').innerHTML='<div class="band-labels" style="grid-template-columns:1.2fr 1fr 36px"><span>等级名称</span><span>绩点</span></div>'+rule.ratings.map((r,i)=>'<div class="rating-row" data-rating="'+i+'"><input data-key="name" aria-label="等级 '+(i+1)+' 名称" value="'+esc(r.name)+'"><input data-key="gpa" type="number" min="0" step="any" aria-label="等级 '+(i+1)+' 绩点" value="'+esc(r.gpa)+'"><button class="icon-button" data-remove-rating="'+i+'" aria-label="删除等级 '+(i+1)+'">×</button></div>').join('');}
  function loadExample(){if(courses.length&&!confirm('载入示例会替换当前累计成绩、课程与规则，继续吗？'))return;const e=core.example();courses=e.courses;rule=e.rule;for(const [id,k] of [['current-gpa','currentGpa'],['history-credits','historyCredits'],['history-points','historyPoints'],['target-gpa','target']])$(id).value=e[k];$('precision-details').open=true;$('rule-template').value='five';renderRule();renderCourses();calculate();toast('已载入虚构示例，可修改目标绩点。');}
  $('load-example').addEventListener('click',loadExample);$('calculate').addEventListener('click',()=>{calculate();$('plan-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});
  for(const id of ['current-gpa','history-credits','history-points','target-gpa'])$(id).addEventListener('input',refresh);
  document.querySelectorAll('[data-target]').forEach(b=>b.addEventListener('click',()=>{$('target-gpa').value=b.dataset.target;refresh();}));
  $('add-course').addEventListener('click',()=>{courses.push({id:uid(),name:'',credits:'',type:'numeric',fixed:''});renderCourses();refresh();$('course-body').lastElementChild.querySelector('input').focus();});
  $('course-body').addEventListener('input',e=>{const field=e.target.dataset.field;if(!field||e.target.tagName==='SELECT')return;const i=Number(e.target.closest('tr').dataset.index);courses[i][field]=e.target.value;updateCount();refresh();});
  $('course-body').addEventListener('change',e=>{const field=e.target.dataset.field;if(!field||e.target.tagName!=='SELECT')return;const i=Number(e.target.closest('tr').dataset.index);courses[i][field]=e.target.value;if(field==='type'){courses[i].fixed='';renderCourses();}refresh();});
  $('course-body').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;courses.splice(Number(b.dataset.remove),1);lastResult=null;renderCourses();refresh();});
  const ruleFields={'gpa-scale':'scale','rule-mode':'mode','pass-score':'passScore','band-pass-score':'passScore','base-gpa':'base','gpa-step':'step'};
  for(const [id,key] of Object.entries(ruleFields))$(id).addEventListener(id==='rule-mode'?'change':'input',()=>{rule[key]=$(id).value;$('rule-template').value=rule.mode==='bands'?'custom-bands':'custom-linear';if(key==='passScore'){$('pass-score').value=rule.passScore;$('band-pass-score').value=rule.passScore;}updateFormula();refresh();});
  $('rule-template').addEventListener('change',()=>{const mode=$('rule-template').value;if(mode==='five'){if(!confirm('此模板会替换百分制与等级换算规则，请确认适用于你的学校。')){$('rule-template').value=rule.mode==='bands'?'custom-bands':'custom-linear';return;}rule=core.example().rule;}else rule.mode=mode==='custom-bands'?'bands':'linear';renderRule();refreshRatingOptions();refresh();});
  $('band-rows').addEventListener('input',e=>{const row=e.target.closest('[data-band]');if(!row||!e.target.dataset.key)return;rule.bands[Number(row.dataset.band)][e.target.dataset.key]=e.target.value;refresh();});
  $('band-rows').addEventListener('click',e=>{const b=e.target.closest('[data-remove-band]');if(b){rule.bands.splice(Number(b.dataset.removeBand),1);renderBands();refresh();}});
  $('add-band').addEventListener('click',()=>{rule.bands.push({min:rule.bands.at(-1)?.max||'0',max:'100',gpa:''});renderBands();refresh();});
  $('rating-rows').addEventListener('input',e=>{const row=e.target.closest('[data-rating]');if(!row||!e.target.dataset.key)return;rule.ratings[Number(row.dataset.rating)][e.target.dataset.key]=e.target.value;refreshRatingOptions();refresh();});
  $('rating-rows').addEventListener('click',e=>{const b=e.target.closest('[data-remove-rating]');if(b){rule.ratings.splice(Number(b.dataset.removeRating),1);renderRatings();refreshRatingOptions();refresh();}});
  $('add-rating').addEventListener('click',()=>{rule.ratings.push({name:'',gpa:''});renderRatings();refreshRatingOptions();refresh();});
  function requireXlsx(){if(!globalThis.XLSX)throw new Error('Excel 组件未加载，请确认网页文件完整后重试。');}
  $('download-template').addEventListener('click',()=>{try{requireXlsx();const w=XLSX.utils.book_new(),sheet=XLSX.utils.aoa_to_sheet([['课程名称','学分','评分方式','预计成绩'],['示例：高等数学',3,'百分制',''],['示例：大学体育',1,'等级','']]);sheet['!cols']=[{wch:30},{wch:10},{wch:16},{wch:15}];XLSX.utils.book_append_sheet(w,sheet,'待计入课程');const help=XLSX.utils.aoa_to_sheet([['填写说明'],['第一张工作表用于导入；删除示例行后填写真实课程。'],['评分方式填写“百分制”或“等级”；未填写时在导入预览补选。'],['预计成绩留空表示自动分配；百分制可填小数，等级填写配置中的名称。'],['只填写尚未计入当前累计绩点的课程。'],['累计成绩和学校规则在网页中填写。']]);help['!cols']=[{wch:95}];XLSX.utils.book_append_sheet(w,help,'填写说明');XLSX.writeFile(w,'绩点计划_课程导入模板.xlsx');}catch(e){toast(e.message);}});
  $('import-excel').addEventListener('click',()=>$('excel-file').click());
  $('excel-file').addEventListener('change',async()=>{const file=$('excel-file').files[0];if(!file)return;try{requireXlsx();if(file.size>10*1024*1024)throw new Error('请选择不超过 10 MB 的 Excel 文件');const w=XLSX.read(await file.arrayBuffer(),{type:'array'});if(!w.SheetNames.length)throw new Error('文件中没有工作表');const raw=XLSX.utils.sheet_to_json(w.Sheets[w.SheetNames[0]],{header:1,defval:'',blankrows:true});preview=core.importRows(raw);renderPreview();$('import-dialog').showModal();}catch(e){toast('导入失败：'+e.message);}finally{$('excel-file').value='';}});
  function previewError(c,i){try{core.validateCourse(c,rule,i);return '';}catch(e){return e.message.replace(/^第 \d+ 门课程[：]?/,'');}}
  function renderPreview(){
    $('import-body').innerHTML=preview.map((c,i)=>'<tr data-preview="'+i+'"><td>'+c.sourceRow+'</td><td><input data-field="name" value="'+esc(c.name)+'" aria-label="原始行 '+c.sourceRow+' 课程名称"></td><td><input data-field="credits" type="number" min="0" step="any" value="'+esc(c.credits)+'" aria-label="原始行 '+c.sourceRow+' 学分"></td><td><select data-field="type" aria-label="原始行 '+c.sourceRow+' 评分方式">'+typeOptions(c.type,true)+'</select></td><td>'+(c.type==='rating'?'<select data-field="fixed" aria-label="原始行 '+c.sourceRow+' 预计等级">'+ratingOptions(c.fixed)+'</select>':'<input data-field="fixed" value="'+esc(c.fixed)+'" placeholder="选填" aria-label="原始行 '+c.sourceRow+' 预计成绩">')+'</td><td class="row-error" data-error="'+i+'"></td><td><button class="icon-button" data-remove-preview="'+i+'" aria-label="移除原始行 '+c.sourceRow+'">×</button></td></tr>').join('');checkPreview();
  }
  function checkPreview(){let errors=0;preview.forEach((c,i)=>{const message=previewError(c,i);const e=document.querySelector('[data-error="'+i+'"]');if(e)e.textContent=message?'第 '+c.sourceRow+' 行：'+message:'通过';if(message)errors++;});$('import-message').textContent=errors?'还有 '+errors+' 行需要修正，修正后才能确认导入。':preview.length?'共 '+preview.length+' 门课程，确认后加入现有课程。':'没有待导入课程。';return errors;}
  $('import-body').addEventListener('input',e=>{if(e.target.tagName==='SELECT'||!e.target.dataset.field)return;const i=Number(e.target.closest('tr').dataset.preview);preview[i][e.target.dataset.field]=e.target.value;checkPreview();});
  $('import-body').addEventListener('change',e=>{if(e.target.tagName!=='SELECT'||!e.target.dataset.field)return;const i=Number(e.target.closest('tr').dataset.preview),field=e.target.dataset.field;preview[i][field]=e.target.value;if(field==='type')renderPreview();else checkPreview();});
  $('import-body').addEventListener('click',e=>{const b=e.target.closest('[data-remove-preview]');if(b){preview.splice(Number(b.dataset.removePreview),1);renderPreview();}});
  for(const id of ['close-import','cancel-import'])$(id).addEventListener('click',()=>$('import-dialog').close());
  $('confirm-import').addEventListener('click',()=>{if(checkPreview()||!preview.length)return;try{core.validateRule(rule);}catch(e){$('import-message').textContent='请先关闭预览并修正规则：'+e.message;return;}if(courses.length+preview.length>500){$('import-message').textContent='课程总数不能超过 500 门';return;}courses.push(...preview.map(c=>({...c,id:uid()})));lastResult=null;renderCourses();refresh();$('import-dialog').close();toast('已导入 '+preview.length+' 门课程。');preview=[];});
  $('target-gpa').value='4.0';renderRule();renderCourses();
  // Optional browser-standard agent interface. It invokes the same validated UI actions.
  if(document.modelContext?.registerTool){
    const lifecycle=new AbortController();const tools=[
      {name:'read_gpa_plan',description:'读取当前绩点计算输入与最近结果。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({input:getInput(),result:lastResult})},
      {name:'set_gpa_target_and_calculate',description:'设置目标累计绩点并重新计算，更新网页的目标和各科建议。',inputSchema:{type:'object',properties:{target:{type:'number',minimum:0}},required:['target'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.target!=='number'||!Number.isFinite(input.target))throw new Error('target 必须是有效数字');const candidate=getInput();candidate.target=String(input.target);const result=core.solve(candidate);$('target-gpa').value=String(input.target);calculate();return {feasible:result.feasible,forecast:result.forecast,max:result.max,rows:result.rows};}}
    ];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  }
})();
